UPDATE buildings SET name = CASE id WHEN 11 THEN 'Общежитие №1' ELSE 'Общежитие №2' END, number = CASE id WHEN 11 THEN '1' ELSE '2' END, is_active = TRUE, is_demo_data = TRUE, sort_order = id - 10, updated_at = NOW() WHERE id IN (11, 12);

INSERT INTO rooms (room_number, building, capacity, building_id, floor, is_active, is_demo_data, is_residential)
SELECT f || LPAD(k::text, 2, '0'), CASE b WHEN 11 THEN 'Общежитие №1' ELSE 'Общежитие №2' END, CASE WHEN k IN (1, 8) THEN 3 ELSE 2 END, b, f, TRUE, TRUE, TRUE
FROM (VALUES (11, 3), (12, 2)) bb(b, fl), generate_series(1, 3) f, generate_series(1, 8) k WHERE f <= fl;

INSERT INTO personnel (personal_code, full_name, position, department, category, organization_type, organization, status, gender, phone, room, qr_code, medical_status, shift, is_demo_data, residence, residence_building_id, residence_room_id, pass_number, pass_valid_from, pass_valid_to, vehicle_pass_number, vehicle_number, vehicle_brand, created_at)
SELECT 'ДМ-' || LPAD(v.n::text, 3, '0'), v.fio, v.pos, v.dep, v.cat, v.ot, v.org, v.st, v.g,
  '+7 914 ' || (100 + v.n) || '-' || LPAD((10 + v.n % 80)::text, 2, '0') || '-' || LPAD((20 + v.n % 70)::text, 2, '0'),
  v.rn, 'DMQR-' || LPAD(v.n::text, 3, '0'), 'pending', CASE WHEN v.n % 2 = 1 THEN 'A' ELSE 'B' END, TRUE,
  CASE v.b WHEN 11 THEN 'Общежитие №1' WHEN 12 THEN 'Общежитие №2' ELSE '' END, v.b,
  (SELECT r.id FROM rooms r WHERE r.building_id = v.b AND r.room_number = v.rn AND r.is_demo_data = TRUE),
  'П-' || (7000 + v.n), CURRENT_DATE - 30, CASE WHEN v.n % 11 = 0 THEN CURRENT_DATE + 3 ELSE CURRENT_DATE + 90 + v.n END,
  CASE WHEN v.n IN (5, 12, 21, 30, 44) THEN 'ДМ-А' || LPAD(v.n::text, 3, '0') ELSE '' END,
  CASE WHEN v.n IN (5, 12, 21, 30, 44) THEN 'К' || (v.n % 10) || ((v.n * 3) % 10) || ((v.n * 7) % 10) || 'МН75' ELSE '' END,
  CASE WHEN v.n IN (5, 12, 21, 30, 44) THEN 'КАМАЗ' ELSE '' END,
  NOW() - ((40 - v.n % 30) || ' days')::interval
FROM (VALUES
